// ═══════════════════════════════════════════════════════════════════
// MOTOR DE RECORRÊNCIA — EasyWorkHub · Grupo Espacial (Épico 3)
// Edite APENAS o bloco ROTINAS. O resto é o motor.
// ═══════════════════════════════════════════════════════════════════
const API = 'https://plane.easyworkhub.com.br/api/v1/workspaces/grupo-espacial-motel';
const TOKEN = 'TODO_plane_api_...';

// ── ROTINAS ────────────────────────────────────────────────────────
// frequencia:
//   'diaria'                     todo dia
//   'dias_semana:seg,qua,sex'    dias específicos (dom,seg,ter,qua,qui,sex,sab)
//   'semanal:seg'                1x por semana
//   'mensal:5'                   todo dia 5 (meses sem o dia: não gera)
//   'anual:15/03'                todo 15 de março
//   'cada:3d' | 'cada:2s' | 'cada:1m'   a cada X dias/semanas/meses
//                                (exige "inicio"; mês ≈ 30 dias)
// inicio/fim: 'AAAA-MM-DD' (opcionais) · sufixo_data: título ganha " · DD/MM"
const ROTINAS = [
  {
    id: 'verificar-interditados',
    titulo: 'Verificar apartamentos interditados',
    descricao: 'Passar em todos os apartamentos interditados e registrar a situação de cada um.',
    projeto: 'MNT',
    prioridade: 'high',
    etiquetas: ['Rotina'],
    frequencia: 'diaria',
    sufixo_data: true,
    ativo: true
  },
  {
    id: 'exemplo-semanal',
    titulo: 'Conferir estoque da copa',
    projeto: 'CMP',
    etiquetas: ['Rotina'],
    frequencia: 'semanal:seg',
    sufixo_data: true,
    ativo: false            // ← exemplo desligado; ativar quando quiser
  },
  {
    id: 'exemplo-mensal',
    titulo: 'Fechar planilha de consumo do mês',
    projeto: 'DIR',
    frequencia: 'mensal:1',
    prioridade: 'urgent',
    ativo: false
  }
];
// ── FIM DAS ROTINAS ────────────────────────────────────────────────

// data de hoje no fuso de Brasília (nunca usar o relógio UTC do servidor)
const hoje = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
const dHoje = new Date(hoje + 'T12:00:00Z');
const dow = dHoje.getUTCDay(); // 0=dom … 6=sab
const DIAS = { dom: 0, seg: 1, ter: 2, qua: 3, qui: 4, sex: 5, sab: 6 };
const [ano, mes, dia] = hoje.split('-').map(Number);

function venceHoje(r) {
  if (r.inicio && hoje < r.inicio) return false;
  if (r.fim && hoje > r.fim) return false;
  const [tipo, arg] = r.frequencia.split(':');
  if (tipo === 'diaria') return true;
  if (tipo === 'dias_semana') return arg.split(',').some(d => DIAS[d.trim()] === dow);
  if (tipo === 'semanal') return DIAS[arg.trim()] === dow;
  if (tipo === 'mensal') return dia === Number(arg);
  if (tipo === 'anual') {
    const [dd, mm] = arg.split('/').map(Number);
    return dia === dd && mes === mm;
  }
  if (tipo === 'cada') {
    if (!r.inicio) return false;
    const passo = { d: 1, s: 7, m: 30 }[arg.slice(-1)] * Number(arg.slice(0, -1));
    const diff = Math.round((dHoje - new Date(r.inicio + 'T12:00:00Z')) / 86400000);
    return diff >= 0 && diff % passo === 0;
  }
  return false;
}

// trava: cada rotina gera no máximo 1 vez por dia (sobrevive a reexecuções)
const sd = $getWorkflowStaticData('global');
sd.lastRun = sd.lastRun || {};

const req = (method, url, body) => this.helpers.httpRequest({
  method, url, json: true,
  headers: { 'X-Api-Key': TOKEN, 'Content-Type': 'application/json' },
  body
});
const pausa = ms => new Promise(res => setTimeout(res, ms));

const devidas = ROTINAS.filter(r => r.ativo && venceHoje(r) && sd.lastRun[r.id] !== hoje);
if (!devidas.length) return [{ json: { dia: hoje, criadas: 0, msg: 'nada a gerar' } }];

// resolve projetos uma vez; estados/etiquetas por projeto sob demanda (com cache)
const projs = await req('GET', `${API}/projects/?per_page=100`);
const porIdent = {};
for (const p of (projs.results || projs)) porIdent[p.identifier] = p.id;
const cache = {};
async function contexto(pid) {
  if (!cache[pid]) {
    const [est, lab] = [
      await req('GET', `${API}/projects/${pid}/states/?per_page=100`),
      await req('GET', `${API}/projects/${pid}/labels/?per_page=100`)
    ];
    cache[pid] = {
      estados: est.results || est,
      labels: Object.fromEntries((lab.results || lab).map(l => [l.name, l.id]))
    };
  }
  return cache[pid];
}

const resumo = [];
for (const r of devidas) {
  const pid = porIdent[r.projeto];
  if (!pid) { resumo.push({ rotina: r.id, erro: `projeto ${r.projeto} não existe` }); continue; }
  const ctx = await contexto(pid);
  const estado = ctx.estados.find(s => s.group === 'unstarted');
  const dataBr = `${String(dia).padStart(2, '0')}/${String(mes).padStart(2, '0')}`;
  const titulo = r.titulo + (r.sufixo_data ? ` · ${dataBr}` : '');
  const checklist = (r.checklist || []).map(c => `<li>${c}</li>`).join('');
  const corpo = `<p>${r.descricao || ''}</p>` +
    (checklist ? `<ul class="todo-list">${checklist}</ul>` : '') +
    `<p><em>Rotina automática (${r.frequencia})</em></p>`;
  const payload = {
    name: titulo,
    description_html: corpo,
    priority: r.prioridade || 'none',
    target_date: hoje,
    labels: (r.etiquetas || []).map(n => ctx.labels[n]).filter(Boolean)
  };
  if (estado) payload.state = estado.id;
  const criado = await req('POST', `${API}/projects/${pid}/work-items/`, payload);
  sd.lastRun[r.id] = hoje;
  resumo.push({ rotina: r.id, item: criado.id, titulo });
  await pausa(1200);
}
return [{ json: { dia: hoje, criadas: resumo.filter(x => x.item).length, resumo } }];
